"use client";

import { type HTMLAttributes, useState } from "react";
import { cx } from "../utils/cx";

export type AvatarProps = HTMLAttributes<HTMLSpanElement> & {
  src?: string;
  /** The person or entity's name: the image's alt text and the source of the initials fallback. */
  name: string;
  size?: "xs" | "sm" | "md" | "lg" | "xl";
  shape?: "circle" | "square";
  /** A status dot in the corner. */
  status?: "online" | "away" | "busy" | "offline";
};

const initials = (name: string) =>
  name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((w) => w[0]?.toUpperCase())
    .join("");

/** Hue (0-359) derived from the name, so each fallback has its own stable tint. */
const hueOf = (name: string) => {
  let h = 0;
  for (const c of name) h = (h * 31 + c.charCodeAt(0)) % 360;
  return h;
};

/**
 * A photo with an initials fallback (shown while loading, and if the image fails). The fallback is tinted from the
 * name, so a list of people is distinguishable at a glance.
 */
export function Avatar({ src, name, size = "md", shape = "circle", status, className, style, ...rest }: AvatarProps) {
  const [failed, setFailed] = useState(false);
  const [loaded, setLoaded] = useState(false);
  return (
    <span
      {...rest}
      className={cx("hm-avatar", className)}
      data-size={size}
      data-shape={shape}
      style={{ "--_h": hueOf(name), ...style } as React.CSSProperties}
      role="img"
      aria-label={name}
    >
      <span className="hm-avatar-fallback" aria-hidden="true">
        {initials(name)}
      </span>
      {src && !failed ? (
        <img
          className="hm-avatar-img"
          src={src}
          alt=""
          data-loaded={loaded ? "" : undefined}
          onLoad={() => setLoaded(true)}
          onError={() => setFailed(true)}
        />
      ) : null}
      {status ? <span className="hm-avatar-status" data-status={status} /> : null}
    </span>
  );
}

export type AvatarGroupProps = HTMLAttributes<HTMLDivElement> & {
  /** Show at most this many children, then a "+N" chip. */
  max?: number;
  /** Total people when more than the children given (shows "+N" from this). */
  total?: number;
};

/** Overlapping avatars with a "+N" overflow chip. */
export function AvatarGroup({ max, total, className, children, ...rest }: AvatarGroupProps) {
  const items = Array.isArray(children) ? children : children ? [children] : [];
  const shown = max === undefined ? items : items.slice(0, max);
  const extra = (total ?? items.length) - shown.length;
  return (
    <div {...rest} className={cx("hm-avatar-group", className)} role="group">
      {shown}
      {extra > 0 ? (
        <span
          className="hm-avatar hm-avatar-more"
          data-size="md"
          data-shape="circle"
          role="img"
          aria-label={`${extra} more`}
        >
          <span className="hm-avatar-fallback" aria-hidden="true">
            +{extra}
          </span>
        </span>
      ) : null}
    </div>
  );
}
